22	 * Maps Owner & OwnerDto using Mapstruct
23	 */
24	@Mapper(uses = PetMapper.class)
25	public interface OwnerMapper {
26	
27	    @Mapping(target = "displayName",
28	        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
29	    @Mapping(target = "initials",
30	        expression = "java(owner.getFirstName().substring(0, 1).toUpperCase() + \".\" "
31	            + "+ owner.getLastName().substring(0, 1).toUpperCase() + \".\")")
32	    @Mapping(target = "membershipPoints",
33	        expression = "java(toMembershipPoints(owner))")
34	    @Mapping(target = "membershipLevel",
35	        expression = "java(toMembershipLevel(owner))")
36	    @Mapping(target = "locality",
37	        expression = "java(toLocality(owner))")
38	    @Mapping(target = "ownerSegment",
39	        expression = "java(toOwnerSegment(owner))")
40	    @Mapping(target = "timezone",
41	        expression = "java(toTimezone(owner))")
42	    @Mapping(target = "contactPreference",
43	        expression = "java(toContactPreference(owner))")
44	    @Mapping(target = "identityKey",
45	        expression = "java(toIdentityKey(owner))")
46	    @Mapping(target = "checkDigit",
47	        expression = "java(toCheckDigit(owner))")
48	    @Mapping(target = "ageBand",
49	        expression = "java(toAgeBand(owner))")
50	    @Mapping(target = "telephoneDisplay",
51	        expression = "java(toTelephoneDisplay(owner))")
52	    @Mapping(target = "salutation",
53	        expression = "java(toSalutation(owner))")
54	    @Mapping(target = "fiscalYear",
55	        expression = "java(toFiscalYear(owner))")
56	    @Mapping(target = "selfLink",
57	        expression = "java(toSelfLink(owner))")
58	    OwnerDto toOwnerDto(Owner owner);
