60	    /**
61	     * Derive an owner's canonical self link: the resource path {@code '/api/owners/<id>'} where
62	     * {@code <id>} is the owner's id. Returns {@code null} when the owner has no id yet (the field is
63	     * then absent from the DTO).
64	     */
65	    default String toSelfLink(Owner owner) {
66	        return owner.getId() == null ? null : "/api/owners/" + owner.getId();
67	    }
68	
69	    /**
70	     * The fiscal year that the given date falls in, where the fiscal year starts on 1 July and is
71	     * identified by the calendar year in which it ends. A date on or after 1 July belongs to the
72	     * fiscal year ending in the following calendar year (e.g. 2026-08-01 -&gt; 2027), while a date
73	     * before 1 July belongs to the fiscal year ending in the same calendar year (e.g. 2026-03-01 -&gt;
74	     * 2026). This is the single source of truth for the fiscal year used by both the DTO's
75	     * {@code fiscalYear} and the create endpoint's membership-number year segment.
76	     *
77	     * @param date the date to resolve, on a business day
78	     * @return the calendar year in which that date's fiscal year ends
79	     */
80	    static int fiscalYear(LocalDate date) {
81	        int year = date.getYear();
82	        return date.getMonthValue() >= Month.JULY.getValue() ? year + 1 : year;
83	    }
84	
85	    /**
86	     * Derive an owner's fiscal year from its business-day-adjusted {@code registrationDate},
87	     * formatted {@code 'FY<YY>'} where YY is the last two digits of the fiscal year (see
88	     * {@link #fiscalYear(LocalDate)}), e.g. {@code 'FY27'}. Returns {@code null} when no registration
89	     * date is present (the field is then absent from the DTO).
90	     */
91	    default String toFiscalYear(Owner owner) {
92	        LocalDate registrationDate = owner.getRegistrationDate();
93	        return registrationDate == null ? null : String.format("FY%02d", fiscalYear(registrationDate) % 100);
94	    }
95	
96	    /**
97	     * Derive an owner's salutation: the {@code title}, a single space, and the {@code lastName}
98	     * (e.g. {@code "DR Franklin"}). When no title was supplied (null or blank) the salutation is
99	     * just the last name.
100	     */
101	    default String toSalutation(Owner owner) {
102	        String lastName = owner.getLastName();
103	        String title = owner.getTitle();
104	        if (title == null || title.isBlank()) {
105	            return lastName;
106	        }
107	        return title + " " + lastName;
108	    }
109	
110	    /**
111	     * Derive an owner's age band from the {@code birthDate} relative to the {@code registrationDate}:
112	     * 'MINOR' when under 18, 'ADULT' when 18 to 64, and 'SENIOR' when 65 or older. Returns
113	     * {@code null} when no birth date was supplied (the band is then absent from the DTO). When the
114	     * registration date is missing (e.g. legacy records) the current date is used as the reference.
115	     */
116	    default OwnerDto.AgeBandEnum toAgeBand(Owner owner) {
117	        LocalDate birthDate = owner.getBirthDate();
118	        if (birthDate == null) {
119	            return null;
120	        }
121	        LocalDate reference = owner.getRegistrationDate() != null
122	            ? owner.getRegistrationDate() : LocalDate.now();
123	        int age = Period.between(birthDate, reference).getYears();
124	        if (age < 18) {
125	            return OwnerDto.AgeBandEnum.MINOR;
126	        }
127	        if (age < 65) {
128	            return OwnerDto.AgeBandEnum.ADULT;
129	        }
130	        return OwnerDto.AgeBandEnum.SENIOR;
131	    }
132	
133	    /**
134	     * Format an owner's stored E.164 {@code telephone} for humans: the country code, a space, then the
135	     * national digits grouped in threes (e.g. {@code "+61412345678"} becomes {@code "+61 412 345 678"}).
136	     * The raw {@code telephone} property is left untouched in E.164 form. Returns the value unchanged
137	     * when it is {@code null} or not in {@code '+'}-prefixed E.164 form.
138	     *
139	     * <p>The recognized dialling codes come from {@link E164PhoneNumbers}, the same table the create
140	     * endpoint validates against, so the two paths cannot diverge. When a number carries no recognized
141	     * code, a two-digit country code is assumed (the most common length).
142	     */
143	    default String toTelephoneDisplay(Owner owner) {
144	        String telephone = owner.getTelephone();
145	        if (telephone == null || !telephone.startsWith("+")) {
146	            return telephone;
147	        }
148	        String digits = telephone.substring(1);
149	        String code = E164PhoneNumbers.countryCode(digits)
150	            .filter(c -> digits.length() > c.length())
151	            .orElse(digits.length() > 2 ? digits.substring(0, 2) : digits);
152	        String national = digits.substring(code.length());
153	        StringBuilder sb = new StringBuilder("+").append(code);
154	        for (int i = 0; i < national.length(); i += 3) {
155	            sb.append(' ').append(national, i, Math.min(i + 3, national.length()));
156	        }
157	        return sb.toString();
158	    }
159	
160	    /**
161	     * Derive an owner's check digit: a single Luhn check digit (0-9) computed over the digits
162	     * contained in the {@code customerCode}. Non-digit characters (the separators) are ignored.
163	     */
164	    default Integer toCheckDigit(Owner owner) {
165	        String code = owner.getCustomerCode();
166	        if (code == null) {
167	            return null;
168	        }
169	        int sum = 0;
170	        boolean dbl = true;
171	        for (int i = code.length() - 1; i >= 0; i--) {
172	            char c = code.charAt(i);
173	            if (c < '0' || c > '9') {
174	                continue;
175	            }
176	            int d = c - '0';
177	            if (dbl) {
178	                d *= 2;
179	                if (d > 9) {
180	                    d -= 9;
181	                }
182	            }
183	            sum += d;
184	            dbl = !dbl;
185	        }
186	        return (10 - (sum % 10)) % 10;
187	    }
188	
189	    /**
190	     * Derive an owner's duplicate-detection identity key: the lower-case SHA-256 hex digest (64
191	     * characters) of the normalized E.164 telephone, the lower-cased email (empty when none) and the
192	     * American Soundex code of the last name, joined with {@code '|'}. Two owners are duplicates only
193	     * when their whole identity keys are equal.
194	     *
195	     * <p>This is the single source of truth for the key: it is both returned on the DTO and used by
196	     * the create endpoint's 409 duplicate check, so the value clients see is exactly the value that
197	     * governs rejection. The "email present" rule reuses {@link #hasEmail(Owner)}, and the Soundex and
198	     * hashing come from {@link IdentityKeyUtils}, the same helpers the soft-match uses.
199	     */
200	    default String toIdentityKey(Owner owner) {
201	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
202	        String email = hasEmail(owner) ? owner.getEmail() : "";
203	        String soundex = IdentityKeyUtils.soundex(owner.getLastName());
204	        return IdentityKeyUtils.sha256Hex(telephone + "|" + email + "|" + soundex);
205	    }
206	
207	    /**
208	     * Whether the owner has an email address present (non-null and non-empty). Single source of truth
209	     * for the "is an email present" rule shared by the derived fields below.
210	     */
211	    default boolean hasEmail(Owner owner) {
212	        return owner.getEmail() != null && !owner.getEmail().isEmpty();
213	    }
214	
215	    /**
216	     * Derive an owner's preferred contact channel: 'EMAIL' when an email address is present,
217	     * otherwise 'PHONE'.
218	     */
219	    default String toContactPreference(Owner owner) {
220	        return hasEmail(owner) ? "EMAIL" : "PHONE";
221	    }
222	
223	    /**
224	     * Derive an owner's membership points: start at 0; add 2 when an email address is present; add 1
225	     * when the owner has no namesakes (namesakeCount is 0); add 2 when the owner belongs to a
226	     * household of 3 or more (see {@link #hasHouseholdBonus(Owner)}); add 3 when the owner's tenure
227	     * is at least one elapsed fiscal year (see {@link #hasTenureBonus(Owner)}). Because a newly
228	     * created owner has zero tenure it never earns the tenure points, so a new owner with an email
229	     * and no namesakes in a single-member household scores 3 points.
230	     */
231	    default Integer toMembershipPoints(Owner owner) {
232	        int points = 0;
233	        if (hasEmail(owner)) {
234	            points += 2;
235	        }
236	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
237	        if (noNamesakes) {
238	            points += 1;
239	        }
240	        if (hasHouseholdBonus(owner)) {
241	            points += 2;
242	        }
243	        if (hasTenureBonus(owner)) {
244	            points += 3;
245	        }
246	        return points;
247	    }
248	
249	    /**
250	     * Whether the owner belongs to a household of 3 or more members. The household size is the count
251	     * of owners sharing the owner's household id, frozen at creation (see the create endpoint).
252	     * Returns {@code false} when no household size is present (e.g. legacy records).
253	     */
254	    default boolean hasHouseholdBonus(Owner owner) {
255	        return owner.getHouseholdSize() != null && owner.getHouseholdSize() >= 3;
256	    }
257	
258	    /**
259	     * Derive an owner's numeric membership level (1 to 4) from its membership points (see
260	     * {@link #toMembershipPoints(Owner)}): level 1 for 0-1 points, 2 for 2-3, 3 for 4-5, and 4 for 6
261	     * or more.
262	     *
263	     * <p>The level is then capped at the owner's {@code membershipLevelCap} when one is present: a new
264	     * owner's membership level cannot exceed one above the current maximum membership level among their
265	     * existing household members, so the cap (frozen at creation, see the create endpoint) is the
266	     * ceiling applied here. When no cap is present (e.g. an owner created with no existing household
267	     * member, or a legacy record) the uncapped level stands.
268	     */
269	    default Integer toMembershipLevel(Owner owner) {
270	        int level = uncappedMembershipLevel(owner);
271	        Integer cap = owner.getMembershipLevelCap();
272	        if (cap != null && level > cap) {
273	            return cap;
274	        }
275	        return level;
276	    }
277	
278	    /**
279	     * Derive an owner's numeric membership level (1 to 4) from its membership points (see
280	     * {@link #toMembershipPoints(Owner)}) before any household ceiling is applied: level 1 for 0-1
281	     * points, 2 for 2-3, 3 for 4-5, and 4 for 6 or more.
282	     */
283	    default Integer uncappedMembershipLevel(Owner owner) {
284	        int points = toMembershipPoints(owner);
285	        if (points <= 1) {
286	            return 1;
287	        }
288	        if (points <= 3) {
289	            return 2;
290	        }
291	        if (points <= 5) {
292	            return 3;
293	        }
294	        return 4;
295	    }
296	
297	    /**
298	     * Whether the owner's tenure is at least one elapsed fiscal year, i.e. the fiscal year of the
299	     * current date is later than the fiscal year of the {@code registrationDate} (fiscal years start
300	     * on 1 July; see {@link #fiscalYear(LocalDate)}). A brand-new owner (registered in the current
301	     * fiscal year) has zero elapsed fiscal years and so never qualifies. Returns {@code false} when
302	     * no registration date is present.
303	     */
304	    default boolean hasTenureBonus(Owner owner) {
305	        LocalDate registrationDate = owner.getRegistrationDate();
306	        if (registrationDate == null) {
307	            return false;
308	        }
309	        return fiscalYear(LocalDate.now()) - fiscalYear(registrationDate) >= 1;
310	    }
311	
312	    /**
313	     * Fixed city-to-region table used as the fall-back when deriving an owner's locality.
314	     */
315	    Map<String, String> CITY_REGION = Map.of(
316	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
317	
318	    /**
319	     * Fixed region-to-inclusive-postcode-range table used to derive an owner's locality from the
320	     * postcode: NSW 2000-2099, VIC 3000-3099, QLD 4000-4099. Each entry is {@code {low, high}}
321	     * inclusive.
322	     */
323	    Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
324	        "NSW", new int[] {2000, 2099},
325	        "VIC", new int[] {3000, 3099},
326	        "QLD", new int[] {4000, 4099});
327	
328	    /**
329	     * Derive an owner's locality (region) from the region-and-hash customer code: the {@code <REGION>}
330	     * segment of the {@code customerCode}, i.e. everything before the first {@code '-'}. Since the
331	     * region is baked into the customer code at creation (see the create endpoint), the locality now
332	     * moves with that identity rather than being recomputed from the postcode and city. When an owner
333	     * has no customer code yet (e.g. legacy records), fall back to deriving the region directly via
334	     * {@link #regionOf(Owner)}.
335	     */
336	    default String toLocality(Owner owner) {
337	        String code = owner.getCustomerCode();
338	        if (code != null) {
339	            int dash = code.indexOf('-');
340	            if (dash > 0) {
341	                return code.substring(0, dash);
342	            }
343	        }
344	        return regionOf(owner);
345	    }
346	
347	    /**
348	     * Derive an owner's marketing segment, formatted {@code '<TIER>_<AREA>'} and one of
349	     * {@code 'PREMIUM_METRO'}, {@code 'PREMIUM_REGIONAL'}, {@code 'STANDARD_METRO'} or
350	     * {@code 'STANDARD_REGIONAL'}. TIER is {@code 'PREMIUM'} when the owner's membership level (see
351	     * {@link #toMembershipLevel(Owner)}) is 3 or more, otherwise {@code 'STANDARD'}. AREA is
352	     * {@code 'METRO'} when the owner's locality (see {@link #toLocality(Owner)}) is a known region
353	     * (NSW, VIC or QLD, i.e. one carrying a {@link #REGION_TIMEZONE} entry), otherwise
354	     * {@code 'REGIONAL'}.
355	     */
356	    default String toOwnerSegment(Owner owner) {
357	        String tier = toMembershipLevel(owner) >= 3 ? "PREMIUM" : "STANDARD";
358	        String area = REGION_TIMEZONE.containsKey(toLocality(owner)) ? "METRO" : "REGIONAL";
359	        return tier + "_" + area;
360	    }
361	
362	    /**
363	     * Fixed region-to-IANA-timezone table used to derive an owner's timezone: NSW -> Australia/Sydney,
364	     * VIC -> Australia/Melbourne, QLD -> Australia/Brisbane.
365	     */
366	    Map<String, String> REGION_TIMEZONE = Map.of(
367	        "NSW", "Australia/Sydney",
368	        "VIC", "Australia/Melbourne",
369	        "QLD", "Australia/Brisbane");
370	
371	    /**
372	     * Derive an owner's IANA timezone name from its locality/region (see {@link #toLocality(Owner)})
373	     * via the fixed {@link #REGION_TIMEZONE} table. Returns {@code null} when the region resolves to no
374	     * entry in the table (e.g. 'UNKNOWN'), so the timezone is then absent from the DTO.
375	     */
376	    default String toTimezone(Owner owner) {
377	        return REGION_TIMEZONE.get(toLocality(owner));
378	    }
379	
380	    /**
381	     * Derive an owner's region, preferring the postcode: when the postcode is present and falls within
382	     * a known region's range (see {@link #REGION_POSTCODE_RANGES}) that region wins. When the postcode
383	     * is absent or in no known range, fall back to the fixed {@link #CITY_REGION} table. Returns
384	     * 'UNKNOWN' when neither the postcode nor the city resolves a region. This is the region baked into
385	     * the {@code <REGION>} segment of a new owner's customer code and, through it, the owner's locality.
386	     */
387	    default String regionOf(Owner owner) {
388	        // Prefer the postcode: the region whose range contains it wins. The logic is kept here (rather
389	        // than in a String -> String helper) because MapStruct would treat such a helper as an implicit
390	        // type conversion and wrongly apply it to other String properties (e.g. telephone).
391	        String postcode = owner.getPostcode();
392	        if (postcode != null) {
393	            try {
394	                int value = Integer.parseInt(postcode.trim());
395	                for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
396	                    int[] range = entry.getValue();
397	                    if (value >= range[0] && value <= range[1]) {
398	                        return entry.getKey();
399	                    }
400	                }
401	            }
402	            catch (NumberFormatException ignored) {
403	                // Non-numeric postcode: fall back to the city table below.
404	            }
405	        }
406	        return CITY_REGION.getOrDefault(owner.getCity(), "UNKNOWN");
407	    }
408	
409	    Owner toOwner(OwnerDto ownerDto);
410	
411	    @Mapping(target = "id", ignore = true)
412	    @Mapping(target = "pets", ignore = true)
413	    Owner toOwner(OwnerFieldsDto ownerDto);
414	
415	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
416	
417	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
418	
419	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
420	        OwnerPageDto ownerPageDto = new OwnerPageDto();
421	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
422	        ownerPageDto.setPage(ownerPage.getNumber());
423	        ownerPageDto.setSize(ownerPage.getSize());
424	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
425	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
426	        return ownerPageDto;
427	    }
428	}
